WITH ValidWebEvents AS (SELECT * FROM web_events WHERE duration_sec BETWEEN 215 AND 344), web_events_stats AS (SELECT CASE WHEN duration_sec >= 428 THEN 'high' WHEN duration_sec >= 120 THEN 'mid' ELSE 'low' END AS duration_sec_bucket, event_type, COUNT(CASE WHEN page = '/home' THEN 1 END) AS home_count, ROUND(STDDEV(duration_sec), 2) AS stddev_duration_sec FROM ValidWebEvents GROUP BY CASE WHEN duration_sec >= 428 THEN 'high' WHEN duration_sec >= 120 THEN 'mid' ELSE 'low' END, event_type) SELECT * FROM web_events_stats WHERE stddev_duration_sec > 73 ORDER BY duration_sec_bucket DESC, event_type LIMIT 3;
